## ステップ2：プレイヤーを{作|つく}る

プレイヤーの{所持金|しょじきん}とインベントリ（{持|も}ち{物|もの}）を{管理|かんり}するオブジェクトを作ろう。

```javascript runnable
let player = {
  name: "ゆうしゃ",
  gold: 2000,
  inventory: [],

  showGold: function() {
    console.log(this.name + "の所持金: " + this.gold + "G");
  },

  showInventory: function() {
    if (this.inventory.length === 0) {
      console.log("持ち物: なし");
      return;
    }
    // 同じアイテムをまとめて数える
    let counts = {};
    for (let i = 0; i < this.inventory.length; i++) {
      let name = this.inventory[i];
      counts[name] = (counts[name] || 0) + 1;
    }
    console.log("=== 持ち物 ===");
    let items = Object.keys(counts);
    for (let i = 0; i < items.length; i++) {
      console.log("  " + items[i] + " x" + counts[items[i]]);
    }
  }
};

player.showGold();
player.showInventory();

// アイテムを追加してみる
player.inventory.push("ポーション");
player.inventory.push("ポーション");
player.inventory.push("エーテル");
player.showInventory();
```

:::sensei
インベントリは{配列|はいれつ}で{管理|かんり}して、{表示|ひょうじ}するときに `reduce` の{考|かんが}え{方|かた}で{数|かず}をまとめているよ。
{同|おな}じアイテムを「x2」のように{表示|ひょうじ}できるのがポイントだね。
:::

## ステップ3：{購入処理|こうにゅうしょり}を{作|つく}る

アイテムを{購入|こうにゅう}する{関数|かんすう}を作ろう。{所持金|しょじきん}チェックもちゃんとやるよ。

```javascript runnable
let shopItems = [
  { name: "ポーション", price: 300, type: "回復" },
  { name: "エーテル", price: 500, type: "回復" },
  { name: "鉄の剣", price: 1200, type: "武器" }
];

let player = {
  name: "ゆうしゃ",
  gold: 1000,
  inventory: []
};

function buyItem(player, shopItems, itemName) {
  // アイテムを探す
  let item = shopItems.find(i => i.name === itemName);

  if (!item) {
    console.log("「" + itemName + "」は売っていません。");
    return false;
  }

  if (player.gold < item.price) {
    console.log("ゴールドが足りません！（必要: " + item.price + "G / 所持: " + player.gold + "G）");
    return false;
  }

  // 購入成功
  player.gold -= item.price;
  player.inventory.push(item.name);
  console.log(item.name + "を購入しました！（-" + item.price + "G）");
  console.log("残りゴールド: " + player.gold + "G");
  return true;
}

// 買い物してみよう
buyItem(player, shopItems, "ポーション");
buyItem(player, shopItems, "エーテル");
buyItem(player, shopItems, "鉄の剣");  // お金が足りない！
```

:::student
お{金|かね}が{足|た}りないとちゃんと{断|ことわ}られる！リアル！
:::

## ステップ4：ショップクラスを{作|つく}る

{全部|ぜんぶ}まとめてクラスにすると、もっと{本格的|ほんかくてき}になるよ。

```javascript runnable
class Shop {
  constructor(name, items) {
    this.name = name;
    this.items = items;
  }

  showMenu() {
    console.log("=== " + this.name + " ===");
    for (let i = 0; i < this.items.length; i++) {
      let item = this.items[i];
      let num = String(i + 1).padStart(2, " ");
      console.log(num + ". " + item.name + "  " + item.price + "G");
    }
  }

  sell(player, itemName) {
    let item = this.items.find(i => i.name === itemName);
    if (!item) {
      console.log("そのアイテムはありません。");
      return false;
    }
    if (player.gold < item.price) {
      console.log("お金が足りないよ！");
      return false;
    }
    player.gold -= item.price;
    player.inventory.push(item.name);
    console.log("「" + item.name + "」を手に入れた！");
    return true;
  }
}

let weaponShop = new Shop("武器屋", [
  { name: "ひのきのぼう", price: 50 },
  { name: "銅の剣", price: 300 },
  { name: "鉄の剣", price: 800 },
  { name: "鋼の剣", price: 2000 }
]);

let player = { name: "ゆうしゃ", gold: 1500, inventory: [] };

weaponShop.showMenu();
console.log("---");
console.log("所持金: " + player.gold + "G");

weaponShop.sell(player, "銅の剣");
weaponShop.sell(player, "鉄の剣");
console.log("所持金: " + player.gold + "G");
console.log("持ち物: " + player.inventory.join(", "));
```

:::sensei
ショップをクラスにすれば、{武器屋|ぶきや}・{道具屋|どうぐや}・{防具屋|ぼうぐや}を{簡単|かんたん}に{作|つく}り{分|わ}けられるよ。
`new Shop("道具屋", [...])` で{新|あたら}しいお{店|みせ}を{作|つく}れるんだ。
