## ステップ5：プレイヤークラスも{作|つく}る

プレイヤーもクラスにして、ショップと{連携|れんけい}させよう。

```javascript runnable
class Player {
  constructor(name, gold) {
    this.name = name;
    this.gold = gold;
    this.inventory = [];
  }

  addItem(itemName) {
    this.inventory.push(itemName);
  }

  hasItem(itemName) {
    return this.inventory.includes(itemName);
  }

  countItem(itemName) {
    let count = 0;
    for (let i = 0; i < this.inventory.length; i++) {
      if (this.inventory[i] === itemName) count++;
    }
    return count;
  }

  showStatus() {
    console.log("--- " + this.name + " ---");
    console.log("ゴールド: " + this.gold + "G");
    if (this.inventory.length === 0) {
      console.log("持ち物: なし");
    } else {
      let counts = {};
      for (let i = 0; i < this.inventory.length; i++) {
        let n = this.inventory[i];
        counts[n] = (counts[n] || 0) + 1;
      }
      let keys = Object.keys(counts);
      let display = keys.map(k => k + " x" + counts[k]);
      console.log("持ち物: " + display.join(", "));
    }
  }
}

let hero = new Player("ゆうしゃ", 3000);
hero.showStatus();

hero.addItem("ポーション");
hero.addItem("ポーション");
hero.addItem("エーテル");
hero.gold -= 1100;

console.log("---");
hero.showStatus();
console.log("ポーション所持: " + hero.countItem("ポーション") + "個");
console.log("テント持ってる？: " + hero.hasItem("テント"));
```

## ステップ6：{完成|かんせい}！ショップシステム

{全|すべ}てのパーツを{組|く}み{合|あ}わせて、{完全|かんぜん}なショップシステムを{作|つく}ろう！

```javascript runnable
class Player {
  constructor(name, gold) {
    this.name = name;
    this.gold = gold;
    this.inventory = [];
  }
  addItem(name) { this.inventory.push(name); }
  getItemCounts() {
    let counts = {};
    for (let i = 0; i < this.inventory.length; i++) {
      let n = this.inventory[i];
      counts[n] = (counts[n] || 0) + 1;
    }
    return counts;
  }
}

class Shop {
  constructor(name, items) {
    this.name = name;
    this.items = items;
  }

  showMenu() {
    console.log("╔══════════════════════╗");
    console.log("  " + this.name);
    console.log("╚══════════════════════╝");
    for (let i = 0; i < this.items.length; i++) {
      let item = this.items[i];
      let num = String(i + 1) + ".";
      let name = item.name.padEnd(10, "　");
      console.log(" " + num + " " + name + " " + item.price + "G");
    }
  }

  buy(player, itemName, quantity) {
    quantity = quantity || 1;
    let item = this.items.find(i => i.name === itemName);
    if (!item) {
      console.log("「" + itemName + "」は置いていないよ。");
      return;
    }
    let total = item.price * quantity;
    if (player.gold < total) {
      console.log("ゴールドが足りない！（" + total + "G必要）");
      return;
    }
    player.gold -= total;
    for (let i = 0; i < quantity; i++) {
      player.addItem(item.name);
    }
    console.log(item.name + " x" + quantity + " を購入！（-" + total + "G）");
  }
}

// ゲームを始めよう！
let hero = new Player("ゆうしゃ", 5000);

let itemShop = new Shop("道具屋マリン", [
  { name: "ポーション", price: 300 },
  { name: "ハイポーション", price: 800 },
  { name: "エーテル", price: 500 },
  { name: "毒消し草", price: 100 },
  { name: "テント", price: 800 }
]);

// ショップ表示
itemShop.showMenu();
console.log("所持金: " + hero.gold + "G");
console.log("");

// お買い物！
console.log("--- お買い物開始 ---");
itemShop.buy(hero, "ポーション", 3);
itemShop.buy(hero, "エーテル", 2);
itemShop.buy(hero, "毒消し草", 5);
itemShop.buy(hero, "テント", 1);
itemShop.buy(hero, "ハイポーション", 5);  // 足りるかな？

// 結果表示
console.log("");
console.log("--- 買い物結果 ---");
console.log("残りゴールド: " + hero.gold + "G");
let counts = hero.getItemCounts();
let itemNames = Object.keys(counts);
for (let i = 0; i < itemNames.length; i++) {
  let n = itemNames[i];
  console.log("  " + n + " x" + counts[n]);
}
```

:::student
すごい！ちゃんとしたお{店|みせ}システムが{完成|かんせい}した！
お{金|かね}が{足|た}りないときもちゃんと{処理|しょり}されてる！
