## ステップ7：{売却機能|ばいきゃくきのう}を{追加|ついか}

{買|か}うだけじゃなく、{売|う}る{機能|きのう}も{追加|ついか}してみよう。

```javascript runnable
class Player {
  constructor(name, gold) {
    this.name = name;
    this.gold = gold;
    this.inventory = [];
  }
  addItem(name) { this.inventory.push(name); }
  removeItem(name) {
    let idx = this.inventory.indexOf(name);
    if (idx === -1) return false;
    this.inventory.splice(idx, 1);
    return true;
  }
  hasItem(name) { return this.inventory.includes(name); }
}

class Shop {
  constructor(name, items) {
    this.name = name;
    this.items = items;
    this.buybackRate = 0.5;  // 買取は半額
  }

  buy(player, itemName) {
    let item = this.items.find(i => i.name === itemName);
    if (!item) { console.log("売っていません。"); return; }
    if (player.gold < item.price) { console.log("お金が足りません！"); return; }
    player.gold -= item.price;
    player.addItem(item.name);
    console.log("購入: " + item.name + "（-" + item.price + "G）");
  }

  sell(player, itemName) {
    if (!player.hasItem(itemName)) {
      console.log(itemName + "を持っていません。");
      return;
    }
    let item = this.items.find(i => i.name === itemName);
    let sellPrice = item ? Math.floor(item.price * this.buybackRate) : 1;
    player.removeItem(itemName);
    player.gold += sellPrice;
    console.log("売却: " + itemName + "（+" + sellPrice + "G）");
  }
}

let hero = new Player("ゆうしゃ", 1000);
let shop = new Shop("よろず屋", [
  { name: "ポーション", price: 300 },
  { name: "鉄の剣", price: 800 }
]);

console.log("所持金: " + hero.gold + "G");
shop.buy(hero, "ポーション");
shop.buy(hero, "鉄の剣");   // 足りない
console.log("所持金: " + hero.gold + "G");

// ポーションを売って資金を増やす
shop.sell(hero, "ポーション");
console.log("所持金: " + hero.gold + "G");

// 今度は買える！
shop.buy(hero, "鉄の剣");
console.log("所持金: " + hero.gold + "G");
console.log("持ち物: " + hero.inventory.join(", "));
```

:::sensei
{売却|ばいきゃく}は{購入|こうにゅう}{価格|かかく}の{半額|はんがく}にしているよ。
`Math.floor()` で{小数点以下|しょうすうてんいか}を{切|き}り{捨|す}てているのもポイントだ。
{実際|じっさい}のRPGでもアイテムの{売値|うりね}は{買値|かいね}より{安|やす}いよね。
:::

## ステップ8：レシート{表示|ひょうじ}

{最後|さいご}に、{買|か}い{物|もの}の{記録|きろく}をレシートとして{表示|ひょうじ}する{機能|きのう}を作ろう！

```javascript runnable
class Player {
  constructor(name, gold) {
    this.name = name;
    this.gold = gold;
    this.inventory = [];
  }
  addItem(name) { this.inventory.push(name); }
}

class Shop {
  constructor(name, items) {
    this.name = name;
    this.items = items;
    this.transactions = [];
  }

  buy(player, itemName, qty) {
    qty = qty || 1;
    let item = this.items.find(i => i.name === itemName);
    if (!item) return;
    let cost = item.price * qty;
    if (player.gold < cost) return;
    player.gold -= cost;
    for (let q = 0; q < qty; q++) player.addItem(item.name);
    this.transactions.push({ name: item.name, qty: qty, price: item.price, total: cost });
  }

  printReceipt(playerName) {
    console.log("┌─────────────────────────┐");
    console.log("│  " + this.name + " レシート");
    console.log("│  お客様: " + playerName);
    console.log("├─────────────────────────┤");
    let grandTotal = 0;
    for (let i = 0; i < this.transactions.length; i++) {
      let t = this.transactions[i];
      console.log("│  " + t.name + " x" + t.qty + "  " + t.total + "G");
      grandTotal += t.total;
    }
    console.log("├─────────────────────────┤");
    console.log("│  合計: " + grandTotal + "G");
    console.log("│  またお越しください！");
    console.log("└─────────────────────────┘");
  }
}

let hero = new Player("ゆうしゃ", 10000);
let shop = new Shop("海の道具屋", [
  { name: "ポーション", price: 300 },
  { name: "エーテル", price: 500 },
  { name: "毒消し草", price: 100 },
  { name: "テント", price: 800 }
]);

// お買い物
shop.buy(hero, "ポーション", 5);
shop.buy(hero, "エーテル", 2);
shop.buy(hero, "毒消し草", 3);
shop.buy(hero, "テント", 1);

// レシート表示
shop.printReceipt(hero.name);
console.log("残りゴールド: " + hero.gold + "G");
```

:::student
レシートまで{出|で}る！{本物|ほんもの}のお{店|みせ}みたいだ！
{今|いま}まで{学|まな}んだこと{全部|ぜんぶ}が{組|く}み{合|あ}わさってるんだね！
:::

:::sensei
そのとおり！この{小|ちい}さなプロジェクトには{今|いま}まで{学|まな}んだ{全|すべ}ての{技術|ぎじゅつ}が{詰|つ}まっているよ。
- オブジェクトとクラスでデータを{整理|せいり}
- {配列|はいれつ}でインベントリと{商品|しょうひん}を{管理|かんり}
- {関数|かんすう}とメソッドで{処理|しょり}をまとめる
- {条件分岐|じょうけんぶんき}で{所持金|しょじきん}チェック
- ループで{表示|ひょうじ}と{計算|けいさん}
- {文字列処理|もじれつしょり}で{見|み}た{目|め}を{整|ととの}える

{全部|ぜんぶ}つながっているんだ。
さあ、{最後|さいご}のチャレンジに{挑戦|ちょうせん}しよう！
